-- Function: public.fn_get_board_child_attendance_summary
-- Backup generated on 2026-10-25 20:33:02

CREATE OR REPLACE FUNCTION public.fn_get_board_child_attendance_summary(p_tenant_id uuid, p_org_id uuid, p_date date, p_branch_id uuid DEFAULT NULL::uuid, p_classroom_id uuid DEFAULT NULL::uuid)  RETURNS TABLE(checked_in integer, checked_out integer, absent integer)  LANGUAGE sql  STABLE AS $function$     SELECT          COUNT(1) FILTER (WHERE ca.status IN ('Present', 'Late'))::int AS checked_in,         COUNT(1) FILTER (WHERE ca.departure_time IS NOT NULL OR ca.status = 'Departed')::int AS checked_out,         COUNT(1) FILTER (WHERE ca.status = 'Absent')::int AS absent     FROM child_attendance ca     JOIN classrooms cl ON ca.classroom_id = cl.id     JOIN branches b ON cl.branch_id = b.id     WHERE ca.tenant_id = p_tenant_id        AND b.organization_id = p_org_id       AND ca.attendance_date = p_date       AND (p_branch_id IS NULL OR cl.branch_id = p_branch_id)       AND (p_classroom_id IS NULL OR cl.id = p_classroom_id); $function$ ;
